-- =====================================================================
-- SmartDesk - V1: schema iniziale
-- 4 tabelle (users, categories, tickets, comments) e 5 chiavi esterne.
-- Gli id usano IDENTITY: nelle entita' JPA usa
--   @GeneratedValue(strategy = GenerationType.IDENTITY)
-- =====================================================================

-- ---------------------------------------------------------------------
-- users  (entita' User)
-- "user" e' una parola riservata in PostgreSQL: la tabella si chiama users
-- ---------------------------------------------------------------------
CREATE TABLE users (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    full_name   VARCHAR(100) NOT NULL,
    email       VARCHAR(255) NOT NULL,
    role        VARCHAR(20)  NOT NULL,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),

    CONSTRAINT uk_users_email UNIQUE (email),
    CONSTRAINT ck_users_role  CHECK (role IN ('CUSTOMER', 'AGENT'))
);

-- ---------------------------------------------------------------------
-- categories  (entita' Category)
-- ---------------------------------------------------------------------
CREATE TABLE categories (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name         VARCHAR(100) NOT NULL,
    description  VARCHAR(500),

    CONSTRAINT uk_categories_name UNIQUE (name)
);

-- ---------------------------------------------------------------------
-- tickets  (entita' Ticket)
-- 3 chiavi esterne: author_id, assignee_id (facoltativa), category_id
-- ---------------------------------------------------------------------
CREATE TABLE tickets (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title        VARCHAR(200) NOT NULL,
    description  TEXT         NOT NULL,   -- nell'entita': @Column(columnDefinition = "TEXT")
    status       VARCHAR(20)  NOT NULL DEFAULT 'OPEN',
    priority     VARCHAR(20)  NOT NULL,
    author_id    BIGINT       NOT NULL,
    assignee_id  BIGINT,                  -- NULL = non ancora assegnato
    category_id  BIGINT       NOT NULL,
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    updated_at   TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    closed_at    TIMESTAMP WITH TIME ZONE,   -- valorizzato quando status = CLOSED

    CONSTRAINT ck_tickets_status   CHECK (status   IN ('OPEN', 'IN_PROGRESS', 'RESOLVED', 'CLOSED')),
    CONSTRAINT ck_tickets_priority CHECK (priority IN ('LOW', 'MEDIUM', 'HIGH', 'URGENT')),

    CONSTRAINT fk_tickets_author   FOREIGN KEY (author_id)   REFERENCES users (id),
    CONSTRAINT fk_tickets_assignee FOREIGN KEY (assignee_id) REFERENCES users (id),
    CONSTRAINT fk_tickets_category FOREIGN KEY (category_id) REFERENCES categories (id)
);

CREATE INDEX idx_tickets_author_id   ON tickets (author_id);
CREATE INDEX idx_tickets_assignee_id ON tickets (assignee_id);
CREATE INDEX idx_tickets_category_id ON tickets (category_id);
CREATE INDEX idx_tickets_status      ON tickets (status);

-- ---------------------------------------------------------------------
-- comments  (entita' Comment)
-- 2 chiavi esterne: ticket_id, author_id
-- Eliminando un ticket si eliminano anche i suoi commenti (ON DELETE CASCADE),
-- coerente con cascade = ALL + orphanRemoval = true su Ticket.comments
-- ---------------------------------------------------------------------
CREATE TABLE comments (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    content     TEXT   NOT NULL,          -- nell'entita': @Column(columnDefinition = "TEXT")
    ticket_id   BIGINT NOT NULL,
    author_id   BIGINT NOT NULL,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),

    CONSTRAINT fk_comments_ticket FOREIGN KEY (ticket_id) REFERENCES tickets (id) ON DELETE CASCADE,
    CONSTRAINT fk_comments_author FOREIGN KEY (author_id) REFERENCES users (id)
);

CREATE INDEX idx_comments_ticket_id ON comments (ticket_id);
CREATE INDEX idx_comments_author_id ON comments (author_id);
